const dashboardTrend = `-- name: DashboardTrend :many
WITH cur AS (SELECT finops.reporting_currency($1, (SELECT d.currency FROM usage.usage_records d
    WHERE d.tenant_id = $1 AND ($2::uuid IS NULL OR d.project_id = $2)
      AND d.recorded_at >= $3 AND d.recorded_at < $4
    GROUP BY d.currency ORDER BY sum(abs(d.billed_cost)) DESC, d.currency LIMIT 1)) AS c),
cost_d AS (
  SELECT date_trunc('day', u.recorded_at) AS d, COALESCE(sum((CASE WHEN u.currency::text = (SELECT c FROM cur) THEN u.billed_cost ELSE finops.convert_cost(u.billed_cost, u.currency::text, (SELECT c FROM cur), u.recorded_at::date) END)), 0) AS cost FROM usage.usage_records u
  WHERE u.tenant_id = $1 AND ($2::uuid IS NULL OR u.project_id = $2)
    AND u.recorded_at >= $3 AND u.recorded_at < $4 GROUP BY 1
), carbon_d AS (
  SELECT date_trunc('day', x.period_start) AS d, sum(x.carbon_kg_co2e) AS co2e FROM carbon.calculations x
  WHERE x.tenant_id = $1 AND ($2::uuid IS NULL OR x.project_id = $2)
    AND x.methodology_version = $5
    AND x.period_start >= $3 AND x.period_start < $4 GROUP BY 1
)
SELECT COALESCE(cost_d.d, carbon_d.d)::timestamptz AS day, COALESCE(cost_d.cost, 0)::float8 AS cost, COALESCE(carbon_d.co2e, 0)::float8 AS carbon_kg_co2e
FROM cost_d FULL JOIN carbon_d ON cost_d.d = carbon_d.d ORDER BY 1
`

type DashboardTrendParams struct {
	TenantID           string    `json:"tenant_id"`
	ProjectID          *string   `json:"project_id"`
	FromTs             time.Time `json:"from_ts"`
	ToTs               time.Time `json:"to_ts"`
	MethodologyVersion string    `json:"methodology_version"`
}

type DashboardTrendRow struct {
	Day          time.Time `json:"day"`
	Cost         float64   `json:"cost"`
	CarbonKgCo2e float64   `json:"carbon_kg_co2e"`
}

func (q *Queries) DashboardTrend(ctx context.Context, arg DashboardTrendParams) ([]DashboardTrendRow, error) {
	rows, err := q.db.Query(ctx, dashboardTrend,
		arg.TenantID,
		arg.ProjectID,
		arg.FromTs,
		arg.ToTs,
		arg.MethodologyVersion,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DashboardTrendRow{}
	for rows.Next() {
		var i DashboardTrendRow
		if err := rows.Scan(&i.Day, &i.Cost, &i.CarbonKgCo2e); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const dashboardVerified = `-- name: DashboardVerified :one
SELECT count(*) FILTER (WHERE outcome IN ('realized','partial'))::int AS verified_count,
       count(*) FILTER (WHERE outcome = 'not_realized')::int AS not_realized_count,
       COALESCE(sum(COALESCE(adjusted_carbon_kg_month, measured_carbon_kg_month)) FILTER (WHERE outcome IN ('realized','partial')), 0)::float8 AS verified_carbon_kg_month,
       COALESCE(sum(COALESCE(adjusted_cost_month, measured_cost_month)) FILTER (WHERE outcome IN ('realized','partial')), 0)::float8 AS verified_saving_month
FROM recommendations.impact_verifications
WHERE tenant_id = $1 AND ($2::uuid IS NULL OR project_id = $2)
`

type DashboardVerifiedParams struct {
	TenantID  string  `json:"tenant_id"`
	ProjectID *string `json:"project_id"`
}

type DashboardVerifiedRow struct {
	VerifiedCount         int32   `json:"verified_count"`
	NotRealizedCount      int32   `json:"not_realized_count"`
	VerifiedCarbonKgMonth float64 `json:"verified_carbon_kg_month"`
	VerifiedSavingMonth   float64 `json:"verified_saving_month"`
}

// What applied recommendations were MEASURED to save (per 30 days), from the impact verification.
func (q *Queries) DashboardVerified(ctx context.Context, arg DashboardVerifiedParams) (DashboardVerifiedRow, error) {
	row := q.db.QueryRow(ctx, dashboardVerified, arg.TenantID, arg.ProjectID)
	var i DashboardVerifiedRow
	err := row.Scan(
		&i.VerifiedCount,
		&i.NotRealizedCount,
		&i.VerifiedCarbonKgMonth,
		&i.VerifiedSavingMonth,
	)
	return i, err
}
